import{_ as t,o as e,c as i,a4 as s}from"./chunks/framework.BUqnS5H7.js";const p=JSON.parse('{"title":"消息队列选型","description":"","frontmatter":{},"headers":[],"relativePath":"rabbitmq/01-basics/chapter-05-mq-comparison.md","filePath":"rabbitmq/01-basics/chapter-05-mq-comparison.md"}'),r={name:"rabbitmq/01-basics/chapter-05-mq-comparison.md"};function l(c,a,d,b,n,m){return e(),i("div",null,[...a[0]||(a[0]=[s(`<h1 id="消息队列选型" tabindex="-1" data-src-line="1" data-src-file="rabbitmq/01-basics/chapter-05-mq-comparison.md">消息队列选型 <a class="header-anchor" href="#消息队列选型" aria-label="Permalink to &quot;消息队列选型&quot;">​</a></h1><blockquote data-src-line="3" data-src-file="rabbitmq/01-basics/chapter-05-mq-comparison.md"><p data-src-line="3" data-src-file="rabbitmq/01-basics/chapter-05-mq-comparison.md">选消息队列不是选「最好的」，而是选「最适合的」。本章聚焦 RabbitMQ 的核心优势与适用场景。完整技术对比见 <a href="/kafka/01-intro/chapter-03-mq-comparison.html">Kafka · 消息队列选型</a>。</p></blockquote><h2 id="rabbitmq-的核心优势" tabindex="-1" data-src-line="5" data-src-file="rabbitmq/01-basics/chapter-05-mq-comparison.md">RabbitMQ 的核心优势 <a class="header-anchor" href="#rabbitmq-的核心优势" aria-label="Permalink to &quot;RabbitMQ 的核心优势&quot;">​</a></h2><table tabindex="0"><thead data-src-line="7" data-src-file="rabbitmq/01-basics/chapter-05-mq-comparison.md"><tr data-src-line="7" data-src-file="rabbitmq/01-basics/chapter-05-mq-comparison.md"><th style="text-align:left;">维度</th><th style="text-align:left;">RabbitMQ 的特点</th></tr></thead><tbody data-src-line="9" data-src-file="rabbitmq/01-basics/chapter-05-mq-comparison.md"><tr data-src-line="9" data-src-file="rabbitmq/01-basics/chapter-05-mq-comparison.md"><td style="text-align:left;">路由能力</td><td style="text-align:left;">4 种 Exchange（Direct/Topic/Fanout/Headers），路由规则灵活</td></tr><tr data-src-line="10" data-src-file="rabbitmq/01-basics/chapter-05-mq-comparison.md"><td style="text-align:left;">延迟</td><td style="text-align:left;">微秒级，比 Kafka 低一个数量级</td></tr><tr data-src-line="11" data-src-file="rabbitmq/01-basics/chapter-05-mq-comparison.md"><td style="text-align:left;">协议支持</td><td style="text-align:left;">AMQP/MQTT/STOMP，IoT 场景天然适配</td></tr><tr data-src-line="12" data-src-file="rabbitmq/01-basics/chapter-05-mq-comparison.md"><td style="text-align:left;">死信队列</td><td style="text-align:left;">原生支持，无需额外开发</td></tr><tr data-src-line="13" data-src-file="rabbitmq/01-basics/chapter-05-mq-comparison.md"><td style="text-align:left;">延迟消息</td><td style="text-align:left;">插件原生支持</td></tr><tr data-src-line="14" data-src-file="rabbitmq/01-basics/chapter-05-mq-comparison.md"><td style="text-align:left;">运维成本</td><td style="text-align:left;">低于 Kafka，轻量级部署</td></tr></tbody></table><h2 id="选-rabbitmq-的场景" tabindex="-1" data-src-line="16" data-src-file="rabbitmq/01-basics/chapter-05-mq-comparison.md">选 RabbitMQ 的场景 <a class="header-anchor" href="#选-rabbitmq-的场景" aria-label="Permalink to &quot;选 RabbitMQ 的场景&quot;">​</a></h2><ul data-src-line="18" data-src-file="rabbitmq/01-basics/chapter-05-mq-comparison.md"><li data-src-line="18" data-src-file="rabbitmq/01-basics/chapter-05-mq-comparison.md">复杂路由规则（按 routing key 精确/模糊匹配）</li><li data-src-line="19" data-src-file="rabbitmq/01-basics/chapter-05-mq-comparison.md">消息量中等（万级 QPS 以内）</li><li data-src-line="20" data-src-file="rabbitmq/01-basics/chapter-05-mq-comparison.md">需要微秒级低延迟</li><li data-src-line="21" data-src-file="rabbitmq/01-basics/chapter-05-mq-comparison.md">IoT 设备通信（MQTT 协议）</li><li data-src-line="22" data-src-file="rabbitmq/01-basics/chapter-05-mq-comparison.md">企业内部微服务间可靠投递</li><li data-src-line="23" data-src-file="rabbitmq/01-basics/chapter-05-mq-comparison.md">需要死信队列、延迟消息等高级特性</li></ul><h2 id="不选-rabbitmq-的场景" tabindex="-1" data-src-line="25" data-src-file="rabbitmq/01-basics/chapter-05-mq-comparison.md">不选 RabbitMQ 的场景 <a class="header-anchor" href="#不选-rabbitmq-的场景" aria-label="Permalink to &quot;不选 RabbitMQ 的场景&quot;">​</a></h2><table tabindex="0"><thead data-src-line="27" data-src-file="rabbitmq/01-basics/chapter-05-mq-comparison.md"><tr data-src-line="27" data-src-file="rabbitmq/01-basics/chapter-05-mq-comparison.md"><th style="text-align:left;">场景</th><th style="text-align:left;">原因</th><th style="text-align:left;">推荐</th></tr></thead><tbody data-src-line="29" data-src-file="rabbitmq/01-basics/chapter-05-mq-comparison.md"><tr data-src-line="29" data-src-file="rabbitmq/01-basics/chapter-05-mq-comparison.md"><td style="text-align:left;">日志收集/大数据流</td><td style="text-align:left;">消息堆积后性能下降</td><td style="text-align:left;">Kafka</td></tr><tr data-src-line="30" data-src-file="rabbitmq/01-basics/chapter-05-mq-comparison.md"><td style="text-align:left;">百万级 QPS</td><td style="text-align:left;">Erlang 单节点瓶颈</td><td style="text-align:left;">Kafka / Pulsar</td></tr><tr data-src-line="31" data-src-file="rabbitmq/01-basics/chapter-05-mq-comparison.md"><td style="text-align:left;">消息回溯</td><td style="text-align:left;">不支持按 offset 回溯</td><td style="text-align:left;">Kafka</td></tr><tr data-src-line="32" data-src-file="rabbitmq/01-basics/chapter-05-mq-comparison.md"><td style="text-align:left;">流处理</td><td style="text-align:left;">无原生流处理引擎</td><td style="text-align:left;">Kafka Streams / Flink</td></tr></tbody></table><h2 id="组合使用" tabindex="-1" data-src-line="34" data-src-file="rabbitmq/01-basics/chapter-05-mq-comparison.md">组合使用 <a class="header-anchor" href="#组合使用" aria-label="Permalink to &quot;组合使用&quot;">​</a></h2><p data-src-line="36" data-src-file="rabbitmq/01-basics/chapter-05-mq-comparison.md">实际项目中经常组合：</p><div class="language-txt vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">txt</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>IoT 设备 ──MQTT──▶ RabbitMQ ──AMQP──▶ 业务服务</span></span>
<span class="line"><span>                                      │</span></span>
<span class="line"><span>                                      ▼</span></span>
<span class="line"><span>                              Kafka（日志/事件流）</span></span></code></pre></div><blockquote data-src-line="45" data-src-file="rabbitmq/01-basics/chapter-05-mq-comparison.md"><p data-src-line="45" data-src-file="rabbitmq/01-basics/chapter-05-mq-comparison.md">不要为了「统一技术栈」强行用一个 MQ 解决所有问题。RabbitMQ 擅长业务消息、灵活路由；Kafka 擅长大数据量、高吞吐。各取所长。</p></blockquote>`,12)])])}const q=t(r,[["render",l]]);export{p as __pageData,q as default};
